class CircularDependencyError(Exception):
    """Exception raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into executable stages (batches).

        :param dependencies: Dictionary mapping task_name -> list of task_names it depends on.
        :return: A list of stages, where each stage is a sorted list of task names.
        :raises CircularDependencyError: If a circular dependency exists.
        """
        # Collect all unique tasks (both keys and listed dependencies)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        prereqs_count = {task: 0 for task in all_tasks}
        dependents = {task: [] for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            prereqs_count[task] = len(unique_deps)
            for dep in unique_deps:
                dependents[dep].append(task)

        # Stage 0: Tasks with no prerequisites
        current_stage = sorted([task for task, count in prereqs_count.items() if count == 0])
        stages = []
        processed_count = 0

        while current_stage:
            stages.append(current_stage)
            processed_count += len(current_stage)
            next_stage = []

            for task in current_stage:
                for dependent in dependents[task]:
                    prereqs_count[dependent] -= 1
                    if prereqs_count[dependent] == 0:
                        next_stage.append(dependent)

            current_stage = sorted(next_stage)

        # If not all tasks were processed, a cycle exists
        if processed_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return stages
