import threading
import time
from collections import deque
from typing import Dict, Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._requests: Dict[str, deque] = {}
        self._lock = threading.Lock()

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        now = timestamp if timestamp is not None else time.time()
        with self._lock:
            dq = self._requests.get(key)
            cutoff = now - self.window_seconds
            if dq:
                while dq and dq[0] <= cutoff:
                    dq.popleft()

            count = len(dq) if dq is not None else 0
            if count < self.max_requests:
                if dq is None:
                    dq = deque()
                    self._requests[key] = dq
                dq.append(now)
                return True, 0.0
            else:
                if not dq:
                    return False, float('inf')
                retry_after = (dq[0] + self.window_seconds) - now
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = timestamp if timestamp is not None else time.time()
        with self._lock:
            dq = self._requests.get(key)
            if dq:
                cutoff = now - self.window_seconds
                while dq and dq[0] <= cutoff:
                    dq.popleft()
                if not dq:
                    del self._requests[key]
                    return max(0, self.max_requests)
                return max(0, self.max_requests - len(dq))
            return max(0, self.max_requests)
