import asyncio
from typing import Any, Callable, Coroutine, List, Optional

_SENTINEL = object()


class AsyncWorkerPool:
    """An asynchronous worker pool implementation using Python standard asyncio

    supporting priority-based task scheduling, worker concurrency control,
    future resolution, and clean shutdown management.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("Concurrency must be greater than 0")
        if max_queue_size <= 0:
            raise ValueError("max_queue_size must be greater than 0")

        self._concurrency = concurrency
        self._max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._is_running = False
        self._is_shutting_down = False
        self._counter = 0

    async def start(self) -> None:
        """Spawns worker tasks to process enqueued tasks."""
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._is_running:
            return

        self._is_running = True
        self._workers = [
            asyncio.create_task(self._worker_loop())
            for _ in range(self._concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Coroutine[Any, Any, Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by pool workers.

        Tasks with higher priority integers are popped and executed before lower priority ones.
        Returns an asyncio.Future that resolves with the result or exception of the task.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut = loop.create_future()

        # Storage format: (-priority, count, coro_func, args, kwargs, fut)
        # Priority is negated so that higher integer priority values are popped first.
        # Monotonic counter guarantees FIFO ordering among equal priorities and avoids
        # uncomparable tuple element errors.
        item = (-priority, self._counter, coro_func, args, kwargs, fut)
        self._counter += 1

        try:
            await self._queue.put(item)
        except Exception:
            if self._is_shutting_down:
                raise RuntimeError("Pool is shutting down")
            raise

        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        return fut

    async def _worker_loop(self) -> None:
        """Worker loop that continuously fetches tasks from the priority queue and executes them."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            should_break = False
            try:
                _, _, coro_func, args, kwargs, fut = item
                if coro_func is _SENTINEL:
                    should_break = True
                elif fut is not None and fut.cancelled():
                    pass
                else:
                    task = asyncio.create_task(coro_func(*args, **kwargs))

                    def _on_fut_cancelled(f: asyncio.Future) -> None:
                        if f.cancelled() and not task.done():
                            task.cancel()

                    if fut is not None:
                        fut.add_done_callback(_on_fut_cancelled)

                    try:
                        res = await task
                        if fut is not None and not fut.done():
                            fut.set_result(res)
                    except asyncio.CancelledError:
                        if not task.done():
                            task.cancel()
                        if fut is not None and not fut.done():
                            fut.cancel()
                        should_break = True
                    except Exception as exc:
                        if fut is not None and not fut.done():
                            fut.set_exception(exc)
            finally:
                self._queue.task_done()

            if should_break:
                break

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """Shuts down the worker pool.

        - If drain=True, waits for all enqueued and active tasks to finish before stopping workers.
        - If drain=False, cancels queued tasks and actively executing worker tasks immediately.
        - Respects optional timeout seconds.
        """
        if self._is_shutting_down:
            return
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain:
                await self._queue.join()
                for _ in range(self._concurrency):
                    item = (float("inf"), self._counter, _SENTINEL, None, None, None)
                    self._counter += 1
                    await self._queue.put(item)
                await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, coro_func, _, _, fut = item
                        if coro_func is not _SENTINEL and fut is not None and not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                for worker in self._workers:
                    worker.cancel()

                await asyncio.gather(*self._workers, return_exceptions=True)

        if timeout is not None:
            try:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            except asyncio.TimeoutError:
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, coro_func, _, _, fut = item
                        if coro_func is not _SENTINEL and fut is not None and not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                for worker in self._workers:
                    worker.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)
        else:
            await _do_shutdown()

        self._is_running = False
