import asyncio
import itertools
from dataclasses import dataclass
from typing import Any, Awaitable, Callable, Optional


@dataclass
class _Job:
    coro_func: Callable[..., Awaitable[Any]]
    args: tuple[Any, ...]
    kwargs: dict[str, Any]
    future: asyncio.Future


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be at least 1")

        self._concurrency = concurrency
        self._queue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._slots = asyncio.Semaphore(max_queue_size)
        self._sequence = itertools.count()

        self._workers: list[asyncio.Task] = []
        self._running: set[asyncio.Future] = set()

        self._state_lock = asyncio.Lock()
        self._shutdown_lock = asyncio.Lock()
        self._shutting_down = False
        self._closed = False

    async def start(self) -> None:
        async with self._state_lock:
            if self._shutting_down or self._closed:
                raise RuntimeError("Pool is shutting down")

            self._workers = [worker for worker in self._workers if not worker.done()]
            if self._workers:
                return

            self._workers = [
                asyncio.create_task(self._worker(), name=f"async-worker-pool-{i}")
                for i in range(self._concurrency)
            ]

    async def submit(
        self,
        coro_func: Callable[..., Awaitable[Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        async with self._state_lock:
            if self._shutting_down or self._closed:
                raise RuntimeError("Pool is shutting down")

        await self._slots.acquire()
        try:
            async with self._state_lock:
                if self._shutting_down or self._closed:
                    raise RuntimeError("Pool is shutting down")

                future = asyncio.get_running_loop().create_future()
                job = _Job(coro_func=coro_func, args=args, kwargs=kwargs, future=future)
                self._queue.put_nowait((-priority, next(self._sequence), job))
                return future
        except BaseException:
            self._slots.release()
            raise

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        async with self._shutdown_lock:
            async with self._state_lock:
                if self._closed:
                    return

                self._shutting_down = True
                self._workers = [worker for worker in self._workers if not worker.done()]

                if drain and not self._workers:
                    self._workers = [
                        asyncio.create_task(
                            self._worker(), name=f"async-worker-pool-{i}"
                        )
                        for i in range(self._concurrency)
                    ]

            try:
                operation = self._drain_and_stop() if drain else self._abort_and_stop()

                if timeout is None:
                    await operation
                else:
                    await asyncio.wait_for(operation, timeout=timeout)
            except asyncio.TimeoutError:
                self._discard_queued_jobs()
                self._cancel_running_jobs()
                self._cancel_workers()
            finally:
                async with self._state_lock:
                    self._closed = True

    async def _worker(self) -> None:
        while True:
            _, _, job = await self._queue.get()

            try:
                if job is None:
                    return

                self._slots.release()

                if job.future.cancelled():
                    continue

                self._running.add(job.future)
                try:
                    result = await job.coro_func(*job.args, **job.kwargs)
                except asyncio.CancelledError:
                    if not job.future.done():
                        job.future.cancel()
                    raise
                except BaseException as exc:
                    if not job.future.done():
                        job.future.set_exception(exc)
                else:
                    if not job.future.done():
                        job.future.set_result(result)
                finally:
                    self._running.discard(job.future)
            finally:
                self._queue.task_done()

    async def _drain_and_stop(self) -> None:
        await self._queue.join()
        await self._stop_workers()

    async def _abort_and_stop(self) -> None:
        self._discard_queued_jobs()
        self._cancel_running_jobs()
        self._cancel_workers()

        workers = [worker for worker in self._workers if not worker.done()]
        if workers:
            await asyncio.gather(*workers, return_exceptions=True)

        self._workers.clear()

    async def _stop_workers(self) -> None:
        workers = [worker for worker in self._workers if not worker.done()]

        for _ in workers:
            await self._queue.put((0, next(self._sequence), None))

        if workers:
            await asyncio.gather(*workers, return_exceptions=True)

        self._workers.clear()

    def _discard_queued_jobs(self) -> None:
        while True:
            try:
                _, _, job = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break

            try:
                if job is not None:
                    self._slots.release()
                    if not job.future.done():
                        job.future.cancel()
            finally:
                self._queue.task_done()

    def _cancel_running_jobs(self) -> None:
        for future in tuple(self._running):
            if not future.done():
                future.cancel()

    def _cancel_workers(self) -> None:
        for worker in self._workers:
            if not worker.done():
                worker.cancel()
