import base64
import json
import hmac
import hashlib
import time

def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] | None = None,
) -> dict:
    if allowed_algs is None:
        allowed_algs = ["HS256"]

    def decode_base64url(value: str) -> bytes:
        padding = "=" * (-len(value) % 4)
        return base64.urlsafe_b64decode(value + padding)

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(decode_base64url(parts[0]))
        payload = json.loads(decode_base64url(parts[1]))
    except (ValueError, json.JSONDecodeError) as exc:
        raise ValueError("Invalid JWT encoding") from exc

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT content")

    alg = header.get("alg")
    if alg not in allowed_algs or alg != "HS256":
        raise ValueError("Unapproved JWT algorithm")

    now = time.time()
    if "exp" in payload and payload["exp"] <= now:
        raise ValueError("Token expired")

    try:
        signature = decode_base64url(parts[2])
    except ValueError as exc:
        raise ValueError("Invalid JWT signature encoding") from exc

    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")
    expected_sig = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        hashlib.sha256,
    ).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
