# No nested or ambiguous quantifiers: linear-time matching.
MARKDOWN_LINK_REGEX = re.compile(
    r'\[([A-Za-z0-9_ ]+)\]\((https?://[^\s)]+)\)'
)

def parse_markdown_links(text: str) -> list[dict[str, str]]:
