import threading


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than zero")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._closed = False
        self._next_id = 1
        self._pool = [self._create_connection() for _ in range(max_connections)]
        self._leased_ids = set()

    def _create_connection(self) -> dict:
        connection = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return connection

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._pool:
                raise RuntimeError("Pool exhausted")

            conn = self._pool.pop()
            self._leased_ids.add(conn["id"])
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            if not isinstance(conn, dict) or "id" not in conn:
                raise ValueError("Invalid connection")

            if conn["id"] not in self._leased_ids:
                raise ValueError("Connection was not acquired from this pool")

            self._leased_ids.remove(conn["id"])

            if not self._closed:
                self._pool.append(conn)

    def health_check_and_heal(self) -> int:
        healed = 0

        with self._lock:
            for index, conn in enumerate(self._pool):
                if not conn.get("alive", False):
                    self._pool[index] = self._create_connection()
                    healed += 1

        return healed

    def close_all(self) -> None:
        with self._lock:
            for conn in self._pool:
                conn["alive"] = False

            self._pool.clear()
            self._leased_ids.clear()
            self._closed = True
